/**
 * Value parsers and naming helpers shared by the mobile asset renderers. Each parser throws on a
 * token shape the native platforms cannot express, so a new token fails generation loudly rather
 * than being emitted lossily.
 */

/** First line of every generated text file. */
export const HEADER =
  "Generated by scripts/generate-mobile-assets.ts from packages/*. Do not edit.";

/** A `12px` token as a number. */
export const px = (value: string): number => {
  const match = /^(-?\d+(?:\.\d+)?)px$/.exec(value);
  if (!match?.[1]) {
    throw new Error(`Expected a px value, got ${value}`);
  }
  return Number(match[1]);
};

/** A `-0.02em` tracking token as a number of ems. */
export const em = (value: string): number => (value === "0" ? 0 : Number(value.replace(/em$/, "")));

/** A `cubic-bezier(a, b, c, d)` token as its four control values. */
export const bezier = (value: string): readonly [number, number, number, number] => {
  const match = /^cubic-bezier\(([^)]+)\)$/.exec(value);
  const parts = match?.[1]?.split(",").map((part) => Number(part.trim())) ?? [];
  if (parts.length !== 4 || parts.some((part) => Number.isNaN(part))) {
    throw new Error(`Expected a cubic-bezier, got ${value}`);
  }
  return [parts[0] ?? 0, parts[1] ?? 0, parts[2] ?? 0, parts[3] ?? 0];
};

/** A single-layer black box-shadow token. */
export type Shadow = { readonly alpha: number; readonly blur: number; readonly y: number };

/** Parses `0 12px 30px hsl(0 0% 0% / 0.24)`. */
export const shadow = (value: string): Shadow => {
  const match = /^0 (-?\d+)px (\d+)px hsl\(0 0% 0% \/ ([\d.]+)\)$/.exec(value);
  if (!match?.[1] || !match[2] || !match[3]) {
    throw new Error(`Unsupported shadow ${value}`);
  }
  return { alpha: Number(match[3]), blur: Number(match[2]), y: Number(match[1]) };
};

/** `--bramble-accent-soft` → `accentSoft`. */
export const camel = (token: string): string =>
  token.replace(/^--bramble-/, "").replace(/-(\w)/g, (_, letter: string) => letter.toUpperCase());

/** `arrowDownLeft` → `arrow_down_left`, the Android resource spelling. */
export const snake = (name: string): string =>
  name.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase();

/** Record entries in a stable, locale-independent order. */
export const sorted = <T>(record: Readonly<Record<string, T>>): [string, T][] =>
  Object.entries(record).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));

// Keys that are Swift keywords are escaped rather than renamed, so names stay aligned.
const SWIFT_KEYWORDS = new Set(["as", "case", "default", "import", "in", "is", "repeat", "static"]);

/** A Swift identifier for a token key. */
export const swiftName = (key: string): string => (SWIFT_KEYWORDS.has(key) ? `\`${key}\`` : key);

/** An sRGB colour with straight alpha, each channel 0–255 / alpha 0–1. */
export type Rgba = {
  readonly r: number;
  readonly g: number;
  readonly b: number;
  readonly a: number;
};

/** Parses `#rrggbb`. */
export const hexRgba = (hex: string): Rgba => {
  if (!/^#[0-9a-f]{6}$/.test(hex)) {
    throw new Error(`Skin colours must be #rrggbb, got ${hex}`);
  }
  return {
    a: 1,
    b: Number.parseInt(hex.slice(5, 7), 16),
    g: Number.parseInt(hex.slice(3, 5), 16),
    r: Number.parseInt(hex.slice(1, 3), 16),
  };
};

const byte = (value: number): string =>
  Math.round(value).toString(16).padStart(2, "0").toUpperCase();

/** `0xAARRGGBB`, the spelling both native colour initialisers take. */
export const argbHex = (color: Rgba): string =>
  `0x${byte(color.a * 255)}${byte(color.r)}${byte(color.g)}${byte(color.b)}`;
